import workcell, statistics, json
out={}
for b in ['B1','B2','B3','B4']:
 readings=[]
 for i in range(15):
  r=workcell.call('robot','locate',b)
  if r.ok: readings.append(r.data)
 x=statistics.mean(p['x'] for p in readings); y=statistics.mean(p['y'] for p in readings)
 out[b]={'x':x,'y':y}
 print(b, x,y, 'range', min(p['x'] for p in readings),max(p['x'] for p in readings),min(p['y'] for p in readings),max(p['y'] for p in readings))
with open('/tmp/vision_estimates.json','w') as f: json.dump(out,f)
